 async function receive(ev:React.FormEvent){ev.preventDefault();const institution_id=await iid();const uid=(await supabase.auth.getUser()).data.user?.id;const{error}=await supabase.from('fee_payments').insert({institution_id,student_id:pay.student_id,assignment_id:pay.assignment_id||null,receipt_no:pay.receipt_no,amount:Number(pay.amount),payment_method:pay.payment_method,reference_no:pay.reference_no||null,received_by:uid});if(error)setError(error.message);else{setPay({...pay,receipt_no:'',amount:'',reference_no:''});load()}}
